package ink.warrant.instrument

import android.bluetooth.BluetoothGattCharacteristic
import java.util.UUID

class AcmeH2Driver : Driver {
    override val id: String = "acme-h2-temp"
    override val label: String = "ACME H2 Temperature"
    override val produces: Produces = Produces(
        unit = "Celsius",
        min = -40.0,
        max = 125.0
    )
    override val matches: Match = Match(
        serviceUuids = listOf(UUID.fromString("6e400001-b5a3-f393-e0a9-e50e24dcca9e"))
    )

    override fun characteristicFor(services: List<UUID>): CharacteristicRef? {
        val serviceUuid = UUID.fromString("6e400001-b5a3-f393-e0a9-e50e24dcca9e")
        val charUuid = UUID.fromString("6e400003-b5a3-f393-e0a9-e50e24dcca9e")
        return if (services.contains(serviceUuid)) {
            CharacteristicRef(serviceUuid, charUuid)
        } else {
            null
        }
    }

    override fun decode(raw: ByteArray): Double? {
        if (raw.size < 4) return null
        if (raw[0].toInt() != 1) return null
        val tempLow = raw[2].toInt() and 0xff
        val tempHigh = raw[3].toInt()
        val tempRaw = ((tempHigh shl 8) or tempLow).toShort().toDouble()
        return tempRaw
    }
}

